function startQuestion(){if(isPaused)resumePractice();var s=progress.settings.adaptive?chooseAdaptiveCell():{family:familyById(progress.manual.familyId),level:progress.manual.level};currentQuestion=generateQuestion(s.family.id,s.level,rng.next(),false);recentSignatures.push(currentQuestion.structuralSignature);recentSignatures=recentSignatures.slice(-100);currentStartedAt=Date.now();pausedMs=0;pauseStartedAt=0;submitted=false;renderQuestion();renderPracticeControls();renderCurrentMetrics();}
