function textInputs(){return Array.from(document.querySelectorAll("#answerControls input[data-answer-field]"));}function finePointer(){return window.matchMedia?window.matchMedia("(pointer: fine)").matches:true;}function setActiveInput(input,focus){activeAnswerInput=input||null;textInputs().forEach(function(x){x.classList.toggle("active-keypad-target",x===activeAnswerInput);});updateKeypad();if(focus&&activeAnswerInput&&finePointer())activeAnswerInput.focus();}function nextInput(){var a=textInputs().filter(function(x){return!x.disabled;});if(a.length<2)return;var i=a.indexOf(activeAnswerInput);setActiveInput(a[(i+1+a.length)%a.length],true);}
