function collectAnswers(){var a={};document.querySelectorAll("[data-answer-field]").forEach(function(x){a[x.dataset.answerField]=x.value;});return a;}function submitAnswer(e){e.preventDefault();if(!currentQuestion||isPaused)return;if(submitted){startQuestion();return;}var res=checkQuestion(collectAnswers(),currentQuestion),duration=elapsedMs(),s=getStat(currentQuestion.familyId,currentQuestion.level);s.attempts+=1;s.correct+=res.correct?1:0;s.totalMs+=duration;s.streak=res.correct?s.streak+1:0;s.recent=s.recent.concat([res.correct]).slice(-10);updateMastery(s);saveProgress();submitted=true;document.querySelectorAll("[data-answer-field]").forEach(function(x){x.disabled=true;});updateKeypad();document.getElementById("submitBtn").innerHTML=t("practice.next","Next")+' <span class="key-symbol">↵</span>';document.getElementById("nextBtn").classList.remove("hidden");document.getElementById("skipBtn").classList.add("hidden");keypadButtons.get("submit").textContent=t("practice.next","Next");var f=document.getElementById("feedback");f.className="feedback "+(res.correct?"correct":"incorrect");f.replaceChildren();var strong=document.createElement("strong");strong.textContent=res.correct?t("messages.correct","Correct"):t("messages.notQuite","Not quite");f.appendChild(strong);if(!res.correct){var exp=document.createElement("div");exp.className="expected-code";exp.textContent=t("messages.expected","Expected")+": "+res.expectedText;f.appendChild(exp);}var d=document.createElement("div");d.className="feedback-detail";d.textContent=currentQuestion.explanation+" "+t("messages.time","Time")+": "+PracticeLabUI.formatSeconds(duration)+".";f.appendChild(d);renderCurrentMetrics();renderSummary();}
function pausePractice(){if(isPaused||submitted)return;isPaused=true;pauseStartedAt=Date.now();renderPauseState();}function resumePractice(){if(!isPaused)return;pausedMs+=Date.now()-pauseStartedAt;pauseStartedAt=0;isPaused=false;renderPauseState();}function renderPauseState(){document.querySelector(".practice-main").classList.toggle("paused",isPaused);document.getElementById("pauseBtn").disabled=isPaused||submitted;updateKeypad();}
function renderSummary(){var z=aggregate();document.getElementById("summaryMastery").textContent=(z.practiced?Math.round(z.masteryTotal/z.practiced):0)+"%";document.getElementById("summaryAccuracy").textContent=(z.attempts?Math.round(100*z.correct/z.attempts):0)+"%";document.getElementById("summaryAttempts").textContent=z.attempts;}function renderCurrentMetrics(){if(!currentQuestion)return;var s=getStat(currentQuestion.familyId,currentQuestion.level);document.getElementById("questionMastery").textContent=s.mastery+"% "+t("practice.masterySuffix","mastery");document.getElementById("metricMastery").textContent=s.mastery+"%";document.getElementById("metricAccuracy").textContent=(s.attempts?Math.round(100*s.correct/s.attempts):0)+"%";document.getElementById("metricStreak").textContent=s.streak;document.getElementById("metricAvgTime").textContent=s.attempts?PracticeLabUI.formatSeconds(s.totalMs/s.attempts):"0s";}function renderPracticeControls(){var f=currentQuestion?familyById(currentQuestion.familyId):familyById(progress.manual.familyId);selectorController.render({familyId:f.id,level:currentQuestion?currentQuestion.level:progress.manual.level});document.getElementById("adaptiveModeBtn").classList.toggle("secondary-active",progress.settings.adaptive);document.getElementById("manualModeBtn").classList.toggle("secondary-active",!progress.settings.adaptive);}function setManualSelection(id,l){progress.manual.familyId=familyById(id).id;progress.manual.level=Math.max(1,Math.min(5,Number(l)||1));progress.settings.adaptive=false;saveProgress();startQuestion();}
function renderMatrix(){var c=document.getElementById("matrix");c.replaceChildren();var table=document.createElement("table"),head=document.createElement("thead"),hr=document.createElement("tr");[t("practice.family","Family")].concat(LEVELS.map(function(l){return"L"+l;})).forEach(function(label){var th=document.createElement("th");th.textContent=label;hr.appendChild(th);});head.appendChild(hr);table.appendChild(head);var body=document.createElement("tbody");CATEGORIES.forEach(function(cat){var cr=document.createElement("tr"),cc=document.createElement("th");cc.colSpan=6;cc.textContent=cat.title;cr.appendChild(cc);body.appendChild(cr);FAMILIES.filter(function(f){return f.categoryId===cat.id;}).forEach(function(f){var row=document.createElement("tr"),name=document.createElement("td");name.textContent=f.title;row.appendChild(name);LEVELS.forEach(function(l){var s=getStat(f.id,l),cell=document.createElement("td"),b=document.createElement("button");b.type="button";b.className="level-button "+(s.mastery>=80?"ready":s.attempts?"weak":"");b.dataset.familyId=f.id;b.dataset.level=l;b.innerHTML="L"+l+"<br><span>"+s.mastery+"% · "+s.attempts+"</span>";cell.appendChild(b);row.appendChild(cell);});body.appendChild(row);});});table.appendChild(body);c.appendChild(table);}
function renderStats(){var z=aggregate();document.getElementById("statTotalAttempts").textContent=z.attempts;document.getElementById("statTotalCorrect").textContent=z.correct;document.getElementById("statTotalTime").textContent=PracticeLabUI.formatMinutes(z.totalMs);document.getElementById("statActiveCells").textContent=z.practiced;var cells=Object.keys(progress.stats).map(function(k){var p=k.split(":"),f=FAMILIES.find(function(x){return x.id===p[0];});return f?{family:f,level:Number(p[1]),stat:progress.stats[k]}:null;}).filter(function(x){return x&&x.stat.attempts;});cells.sort(function(a,b){return a.stat.mastery-b.stat.mastery;});function fill(id,sel){var c=document.getElementById(id);c.replaceChildren();if(!sel.length){var p=document.createElement("p");p.textContent=t("stats.noAttemptsYet","No attempts yet");c.appendChild(p);return;}sel.forEach(function(x){var b=document.createElement("button");b.type="button";b.dataset.familyId=x.family.id;b.dataset.level=x.level;b.textContent=x.family.title+" · L"+x.level+" · "+x.stat.mastery+"% ("+x.stat.attempts+" "+t("stats.tries","tries")+")";c.appendChild(b);});}fill("weakList",cells.slice(0,8));fill("strongList",cells.slice().reverse().slice(0,8));}
function renderSettings(){var c=document.getElementById("enabledCategories");c.replaceChildren();CATEGORIES.forEach(function(cat){var row=document.createElement("div"),label=document.createElement("label"),input=document.createElement("input"),span=document.createElement("span");row.className="check-row";input.type="checkbox";input.checked=progress.settings.enabled[cat.id]!==false;input.dataset.categoryId=cat.id;span.textContent=cat.title;label.appendChild(input);label.appendChild(span);row.appendChild(label);c.appendChild(row);});}function renderLearn(){var c=document.getElementById("learnGrid");c.replaceChildren();FAMILIES.forEach(function(f){var card=document.createElement("article"),h=document.createElement("h3"),p=document.createElement("p"),rule=document.createElement("p"),code=document.createElement("code");card.id="learn-"+f.id;card.className="learn-card"+(learnSpotlightId===f.id?" spotlight":"");h.textContent=f.title;p.textContent=f.learn.concept;rule.textContent=f.learn.rules;code.textContent=f.learn.example;card.appendChild(h);card.appendChild(p);card.appendChild(rule);card.appendChild(code);c.appendChild(card);});}function setView(v){progress.view=v;saveProgress();document.querySelectorAll(".view").forEach(function(x){x.classList.toggle("active",x.id==="view-"+v);});document.querySelectorAll("[data-view]").forEach(function(x){x.classList.toggle("active",x.dataset.view===v);});if(v==="matrix")renderMatrix();if(v==="stats")renderStats();if(v==="settings")renderSettings();if(v==="learn"){renderLearn();if(learnSpotlightId){var card=document.getElementById("learn-"+learnSpotlightId);if(card)card.scrollIntoView({block:"center"});}}if(v==="practice"&&!currentQuestion)startQuestion();}function renderAll(){renderSummary();renderPracticeControls();renderMatrix();renderStats();renderSettings();renderLearn();setView(progress.view);}
function wireEvents(){selectorController=PracticeLabUI.createPracticeSelectors({categorySelect:document.getElementById("categorySelect"),familySelect:document.getElementById("familySelect"),levelSelect:document.getElementById("levelSelect"),categories:CATEGORIES,families:FAMILIES,levelLabel:function(l){return"L"+l;},onSelect:function(s){setManualSelection(s.familyId,s.level);}});var editor=PracticeLabUI.createTextEditor(function(){return activeAnswerInput;});var keys="0123456789ABCDEF".split("").map(function(k){return[k,editor.insert(k),{id:k}];});keypadButtons=PracticeLabUI.renderInputGrid(document.getElementById("answerKeypad"),[keys.slice(0,6),keys.slice(6,12),keys.slice(12).concat([["U+",editor.insert("U+"),{id:"Uplus"}],["0x",editor.insert("0x"),{id:"x"}]]),[["Space",editor.insert(" "),{id:"space",variant:"function"}],[",",editor.insert(","),{id:"comma"}],[t("practice.delete","Del"),editor.backspace,{id:"delete",variant:"function"}],[t("practice.clear","Clear"),editor.clear,{id:"clear",variant:"function"}],[t("practice.nextFieldShort","Field →"),nextInput,{id:"nextField",variant:"function"}],[t("practice.check","Check"),function(){document.getElementById("answerForm").requestSubmit();},{id:"submit",variant:"primary"}]]]);document.querySelectorAll("[data-view]").forEach(function(b){b.addEventListener("click",function(){setView(b.dataset.view);});});document.getElementById("adaptiveModeBtn").addEventListener("click",function(){progress.settings.adaptive=true;saveProgress();startQuestion();});document.getElementById("manualModeBtn").addEventListener("click",function(){progress.settings.adaptive=false;saveProgress();startQuestion();});document.getElementById("pauseBtn").addEventListener("click",pausePractice);document.getElementById("resumeBtn").addEventListener("click",resumePractice);document.getElementById("learnCurrentBtn").addEventListener("click",function(){learnSpotlightId=currentQuestion.familyId;setView("learn");});document.getElementById("answerForm").addEventListener("submit",submitAnswer);document.getElementById("nextBtn").addEventListener("click",startQuestion);document.getElementById("skipBtn").addEventListener("click",startQuestion);document.getElementById("matrix").addEventListener("click",function(e){var b=e.target.closest("[data-family-id][data-level]");if(b){setView("practice");setManualSelection(b.dataset.familyId,b.dataset.level);}});["weakList","strongList"].forEach(function(id){document.getElementById(id).addEventListener("click",function(e){var b=e.target.closest("[data-family-id][data-level]");if(b){setView("practice");setManualSelection(b.dataset.familyId,b.dataset.level);}});});document.getElementById("enabledCategories").addEventListener("change",function(e){if(e.target.dataset.categoryId){progress.settings.enabled[e.target.dataset.categoryId]=e.target.checked;saveProgress();}});document.getElementById("exportBtn").addEventListener("click",function(){document.getElementById("dataBox").value=JSON.stringify(progress,null,2);});document.getElementById("copyBtn").addEventListener("click",function(){var b=document.getElementById("dataBox");if(!b.value)b.value=JSON.stringify(progress,null,2);PracticeLabUI.copyText(b.value);});document.getElementById("importBtn").addEventListener("click",function(){try{progress=mergeProgress(JSON.parse(document.getElementById("dataBox").value));saveProgress();currentQuestion=null;renderAll();}catch(e){document.getElementById("dataBox").value=t("messages.invalidJson","Invalid JSON")+": "+e.message;}});document.getElementById("resetBtn").addEventListener("click",function(){if(window.confirm(t("messages.resetConfirm","Reset all local progress?"))){progress=defaultProgress();saveProgress();currentQuestion=null;renderAll();}});document.addEventListener("keydown",function(e){if(e.key==="Enter"&&submitted&&progress.view==="practice"){e.preventDefault();startQuestion();}});}
function runSelfTests(){var fail=[];function assert(n,c){if(!c)fail.push(n);}assert("nine categories",CATEGORIES.length===9);assert("67 families",FAMILIES.length===67);assert("unique",new Set(FAMILIES.map(function(f){return f.id;})).size===67);if(TEXT.localeCode==="sv"){assert("Swedish category coverage",CATEGORIES.every(function(c){return TEXT.categories&&TEXT.categories[c.id];}));assert("Swedish family coverage",FAMILIES.every(function(f){return TEXT.families&&TEXT.families[f.id]&&TEXT.familyRules&&TEXT.familyRules[f.id];}));}for(var cp=0;cp<=0x10FFFF;cp+=257){if(!isScalar(cp))continue;var b=utf8Encode(cp),d=utf8Decode(b);assert("utf8 "+cp,d.ok&&d.scalar===cp);var u=utf16Encode(cp),du=utf16Decode(u);assert("utf16 "+cp,du.ok&&du.scalars[0]===cp);}assert("utf8 landmarks",bytesText(utf8Encode(0x20AC))==="E2 82 AC"&&utf8Decode([0xF0,0x9F,0x98,0x80]).scalar===0x1F600);assert("utf8 rejection",!utf8Decode([0x80]).ok&&!utf8Decode([0xC0,0xAF]).ok&&!utf8Decode([0xED,0xA0,0x80]).ok);assert("utf16",unitsText(utf16Encode(0x1F600))==="D83D DE00"&&!utf16Decode([0xDE00]).ok);assert("normalization",unitsText(normalize([0x65,0x301],"NFC"))==="00E9"&&unitsText(normalize([0xFB01],"NFKD"))==="0066 0069");assert("graphemes",graphemeBoundaries([0x1F469,0x200D,0x1F4BB]).length===2&&graphemeBoundaries([0x65,0x301]).length===2);var englishLeak=/\b(?:which|what|where|this|these|the|under|strict|named|declared|choose|encode|decode|count|result|answer|valid|invalid|scalar|sequence|bytes|units|code point|code points|worktree|contains|produces|means|because|every|only|same|different|first|second|before|after|with|without|from|into|must|can|cannot|does|are|is|not|and|or|then|displayed|required|expected|actual|source|target|mapping|policy|boundary|boundaries|length|text|string|input|output|error|failure|missing|lone|high|low|surrogate|grapheme|cluster|font|glyph|identity|normalization|case|folding|character)\b/i;FAMILIES.forEach(function(f,fi){LEVELS.forEach(function(l){for(var s=0;s<40;s+=1){try{var item=generateQuestion(f.id,l,((fi+1)*100000+l*1000+s+1)>>>0,true);assert("canonical "+f.id+":"+l+":"+s,checkQuestion(item.canonicalAnswer,item).correct);if(TEXT.localeCode==="sv"){var localized=[item.prompt.title].concat(item.prompt.rows,[item.prompt.note,item.explanation],item.fields.map(function(x){return x.label;}),item.fields.reduce(function(a,x){return a.concat((x.options||[]).map(function(o){return o.label;}));},[])).join(" ");assert("Swedish generated "+f.id+":"+l+":"+s,!englishLeak.test(localized));}}catch(e){fail.push("generator "+f.id+":"+l+":"+s+" "+e.message);}}});});if(fail.length){console.error("Unicode self-tests failed",fail.slice(0,100),"total",fail.length);return{ok:false,failures:fail.slice(0,100)};}console.info("Unicode self-tests passed: 67 families, scalar codecs, curated normalization/segmentation, 13,400 generated instances"+(TEXT.localeCode==="sv"?", Swedish generated-text coverage":""));return{ok:true,failures:[]};}
function init(){progress=loadProgress();rng=new Rng((Date.now()^Math.floor(Math.random()*0xFFFFFFFF))>>>0);wireEvents();startQuestion();renderAll();}window.runSelfTests=runSelfTests;window.UnicodeTextPractice={modelId:MODEL_ID,categories:CATEGORIES,families:FAMILIES,generateQuestion:generateQuestion,checkQuestion:checkQuestion,runSelfTests:runSelfTests,oracles:{isScalar:isScalar,utf8Encode:utf8Encode,utf8Decode:utf8Decode,utf8Boundaries:utf8Boundaries,utf16Encode:utf16Encode,utf16Decode:utf16Decode,serializeUnits:serializeUnits,normalize:normalize,graphemeBoundaries:graphemeBoundaries,jsUnits:jsUnits,caseFold:caseFold,legacyDecode:legacyDecode,legacyEncode:legacyEncode}};document.addEventListener("DOMContentLoaded",init);
